-- Semantic embeddings generated locally with Sentence Transformers.
-- Model: sentence-transformers/paraphrase-multilingual-MiniLM-L12-v2 (384 dimensions).
-- Each vector embeds the question and answer together.
CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA extensions;

CREATE TABLE IF NOT EXISTS public.qa (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    question text NOT NULL UNIQUE,
    answer text NOT NULL,
    embedding extensions.vector(384) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);

ON CONFLICT (question) DO UPDATE
SET answer = EXCLUDED.answer, embedding = EXCLUDED.embedding;
